 $doc=(new Documents($db,'a'))->upload('invoice.xml',$bytes,['title'=>'Receipt','kind'=>'receipt','scope'=>'finance','links'=>[]],bin2hex(random_bytes(16)));denied(fn()=>$r->runInventory($doc,1,$item),'existing document must belong to exact item');
